android.extraProguardRules:
# --- Atributos necesarios para reflexión, Kotlin y trazas legibles ---
-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod,Exceptions
-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile
-keep class kotlin.Metadata { *; }

# --- React Native (bridge, TurboModules, Fabric, JNI, Hermes) ---
-keep class com.facebook.react.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.soloader.** { *; }
-keep class com.facebook.yoga.** { *; }
-keep class com.facebook.fbreact.specs.** { *; }
-keep @com.facebook.proguard.annotations.DoNotStrip class *
-keep @com.facebook.common.internal.DoNotStrip class *
-keepclassmembers class * {
    @com.facebook.proguard.annotations.DoNotStrip *;
    @com.facebook.common.internal.DoNotStrip *;
    @com.facebook.react.bridge.ReactMethod *;
    @com.facebook.react.uimanager.annotations.ReactProp *;
    @com.facebook.react.uimanager.annotations.ReactPropGroup *;
}
-keepclassmembers class * implements com.facebook.react.bridge.JavaScriptModule { *; }
-keepclasseswithmembernames,includedescriptorclasses class * { native <methods>; }

# --- Expo Modules (definiciones por reflexión de Kotlin) ---
-keep class expo.modules.** { *; }
-keep class * extends expo.modules.kotlin.modules.Module { *; }
-keep class * implements expo.modules.kotlin.records.Record { *; }

# --- Librerías nativas autolinkadas ---
-keep class com.swmansion.rnscreens.** { *; }
-keep class com.th3rdwave.safeareacontext.** { *; }
-keep class com.shopify.reactnative.flash_list.** { *; }
-keep class com.reactnativecommunity.** { *; }
-keep class com.reactcommunity.rndatetimepicker.** { *; }

# --- Avisos inocuos de dependencias transitivas ---
-dontwarn com.facebook.react.**
-dontwarn expo.modules.**
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn org.conscrypt.**
-dontwarn org.bouncycastle.**
-dontwarn org.openjsse.**
-dontwarn javax.annotation.**
